<?php
use Illuminate\Support\Facades\Route; use App\Http\Controllers\Api\AuthController; use App\Http\Controllers\Api\PpdbController; use App\Http\Controllers\Api\PengajuanPerubahanController; use App\Http\Controllers\Api\AbsensiController; use App\Http\Controllers\Api\RaporController;
Route::post('/login',[AuthController::class,'login'])->middleware('throttle:5,1');
Route::post('/ppdb',[PpdbController::class,'store'])->middleware('throttle:10,1');
Route::middleware('auth:sanctum')->group(function(){Route::post('/logout',[AuthController::class,'logout']);Route::middleware('permission:ppdb.verify')->group(function(){Route::get('/ppdb',[PpdbController::class,'index']);Route::post('/ppdb/{id}/verifikasi',[PpdbController::class,'verifikasi']);});Route::post('/pengajuan-perubahan',[PengajuanPerubahanController::class,'store']);Route::post('/pengajuan-perubahan/{id}/keputusan',[PengajuanPerubahanController::class,'keputusan'])->middleware('permission:siswa.update.approve');Route::get('/absensi/rekap',[AbsensiController::class,'rekap'])->middleware('permission:akademik.manage');Route::post('/rapor/nilai-akhir',[RaporController::class,'nilaiAkhir'])->middleware('permission:akademik.manage');});
